(function(){
'use strict';
const U='https://bpnkouymdvcogeaqjmxl.supabase.co',K='sb_publishable_v6rJbF4IfGZTKtbuQtmsmQ_lS3sXWFa';
const $=id=>document.getElementById(id);
function esc(v){return String(v==null?'':v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function token(){try{const j=JSON.parse(localStorage.getItem('sb-bpnkouymdvcogeaqjmxl-auth-token')||'null');return j&&((j.currentSession&&j.currentSession.access_token)||(j.session&&j.session.access_token)||j.access_token)||''}catch(e){return''}}
function userKey(){try{const j=JSON.parse(localStorage.getItem('sb-bpnkouymdvcogeaqjmxl-auth-token')||'null');const s=j&&((j.currentSession)||(j.session)||j);if(s&&s.user&&s.user.id)return String(s.user.id);const t=(s&&s.access_token)||'';if(!t)return 'guest';let p=t.split('.')[1]||'';p=p.replace(/-/g,'+').replace(/_/g,'/');while(p.length%4)p+='=';const d=JSON.parse(atob(p));return d.sub?String(d.sub):'guest'}catch(e){return 'guest'}}
function favKey(){return 'dexters-favourite-orders-v1:'+userKey()}
function readFavs(){try{const a=JSON.parse(localStorage.getItem(favKey())||'[]');return Array.isArray(a)?a:[]}catch(e){return[]}}
function writeFavs(a){localStorage.setItem(favKey(),JSON.stringify(a.slice(0,20)))}
async function api(body){const t=token();if(!t)throw Error('Sign in to see your order history.');const r=await fetch(U+'/functions/v1/collection-orders-api',{method:'POST',headers:{apikey:K,Authorization:'Bearer '+t,'Content-Type':'application/json'},body:JSON.stringify(body)});const d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.error||'Could not load orders');return d}
function money(v){const n=Number(v);return Number.isFinite(n)?'£'+n.toFixed(2):esc(v||'')}
function itemsOf(o){return Array.isArray(o.items)?o.items:[]}
function itemSummary(o){const items=itemsOf(o);if(!items.length)return '<div class="tiny muted">Item details unavailable for this older order.</div>';return items.map(i=>{const mods=(i.modifiers||[]).map(m=>'<div class="dx-fav-mod">• '+esc(typeof m==='string'?m:(m.name||m.label||''))+'</div>').join('');return '<div class="dx-fav-line"><span>'+esc(i.qty||1)+' × '+esc(i.base_name||i.name||'Item')+'</span><span>'+money(i.line_total||i.price||'')+'</span></div>'+mods}).join('')}
function reorderUrl(id){return '/collection-order-test.html?reorder='+encodeURIComponent(id)}
function saveFavourite(order){let favs=readFavs().filter(x=>String(x.id)!==String(order.id));favs.unshift({id:order.id,order_number:order.order_number,collection_time:order.collection_time,items:itemsOf(order),saved_at:new Date().toISOString()});writeFavs(favs);renderFavs()}
function removeFavourite(id){writeFavs(readFavs().filter(x=>String(x.id)!==String(id)));renderFavs()}
function renderFavs(){const root=$('dxFavList');if(!root)return;const favs=readFavs();root.innerHTML=favs.length?favs.map(f=>'<div class="dx-fav-order"><div class="row between"><div><strong>Favourite '+esc(f.order_number||'order')+'</strong><div class="tiny muted">'+esc(f.collection_time||'Saved order')+'</div></div></div>'+itemSummary(f)+'<div class="dx-fav-actions"><a class="btn primary" href="'+reorderUrl(f.id)+'">ORDER AGAIN</a><button class="btn secondary" type="button" data-dx-remove="'+esc(f.id)+'">Remove favourite</button></div></div>').join(''):'<p class="muted">No favourites saved yet. Save one from Order History below.</p>';root.querySelectorAll('[data-dx-remove]').forEach(b=>b.onclick=()=>removeFavourite(b.getAttribute('data-dx-remove')))}
async function renderHistory(){const root=$('dxOrderHistory');if(!root)return;root.innerHTML='<p class="muted">Loading order history…</p>';try{const d=await api({action:'my_orders'}),orders=Array.isArray(d.orders)?d.orders:[];root.innerHTML=orders.length?orders.map(o=>'<div class="dx-fav-order"><div class="row between"><div><strong>Order #'+esc(o.order_number||'')+'</strong><div class="tiny muted">'+esc(o.collection_time||'')+'</div></div><span class="pill '+(String(o.status).toLowerCase()==='collected'?'live':'')+'">'+esc(String(o.status||'').toUpperCase())+'</span></div>'+itemSummary(o)+'<div class="dx-fav-actions"><a class="btn primary" href="'+reorderUrl(o.id)+'">ORDER AGAIN</a><button class="btn secondary" type="button" data-dx-save="'+esc(o.id)+'">SAVE AS FAVOURITE</button></div></div>').join(''):'<p class="muted">No collection orders yet.</p>';const byId=new Map(orders.map(o=>[String(o.id),o]));root.querySelectorAll('[data-dx-save]').forEach(b=>b.onclick=()=>{const o=byId.get(String(b.getAttribute('data-dx-save')));if(o){saveFavourite(o);b.textContent='SAVED ✓'}})}catch(e){root.innerHTML='<div class="status err">'+esc(e.message||'Could not load order history.')+'</div>'}}
function ensure(){
 const home=$('homePage');if(!home||$('dxQuickReorderCard'))return;
 const card=document.createElement('div');card.className='card';card.id='dxQuickReorderCard';
 card.innerHTML='<h2>⭐ Favourites & Order Again</h2><p class="muted">Save regular orders and quickly reorder them. Old orders are rechecked against the current menu, prices, stock and modifiers before checkout.</p><div class="tabs"><button id="dxFavTab" class="tab active" type="button">⭐ Favourites</button><button id="dxHistoryTab" class="tab" type="button">🧾 Order History</button></div><div id="dxFavPanel"><div id="dxFavList"></div></div><div id="dxHistoryPanel" class="hidden"><div id="dxOrderHistory"></div></div>';
 home.appendChild(card);
 const style=document.createElement('style');style.id='dxFavStyle';style.textContent='.dx-fav-order{background:#0d1829;border:1px solid #324866;border-radius:16px;padding:14px;margin:10px 0}.dx-fav-line{display:flex;justify-content:space-between;gap:10px;font-size:13px;margin-top:8px}.dx-fav-mod{font-size:12px;color:var(--muted);padding-left:12px;margin-top:3px}.dx-fav-actions{display:flex;gap:8px;margin-top:10px}.dx-fav-actions .btn{padding:10px 12px;font-size:14px;text-align:center;text-decoration:none}.dx-fav-actions a.btn{display:block}@media(max-width:430px){.dx-fav-actions{display:grid;grid-template-columns:1fr}}';document.head.appendChild(style);
 $('dxFavTab').onclick=()=>{$('dxFavPanel').classList.remove('hidden');$('dxHistoryPanel').classList.add('hidden');$('dxFavTab').classList.add('active');$('dxHistoryTab').classList.remove('active');renderFavs()};
 $('dxHistoryTab').onclick=()=>{$('dxHistoryPanel').classList.remove('hidden');$('dxFavPanel').classList.add('hidden');$('dxHistoryTab').classList.add('active');$('dxFavTab').classList.remove('active');renderHistory()};
 renderFavs();
}
function boot(){ensure();setTimeout(ensure,300);setTimeout(ensure,1000);new MutationObserver(ensure).observe(document.body,{childList:true,subtree:true})}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot();
})();

